/**
 * Predefined user avatars.
 *
 * The backend stores and returns only an avatar `id` (GET /api/avatars is the
 * authoritative catalog); the artwork lives here, one SVG per id at
 * src/assets/avatars/<id>.svg (generated by scripts/avatars/generate.mjs).
 *
 * LOCAL_CATALOG mirrors the backend catalog so the picker works offline and
 * never blocks on the network. When the server list loads, it wins, but only
 * ids that have a local asset are shown.
 */

// Every avatar ships as its own file (see build.assetsInlineLimit in
// vite.config.js), so only the eager glob of URLs lands in the bundle.
const assetModules = import.meta.glob("../assets/avatars/*.svg", { eager: true, import: "default" });

const ASSETS = Object.fromEntries(
  Object.entries(assetModules).map(([path, url]) => [path.split("/").pop().replace(/\.svg$/, ""), url]),
);

export const DEFAULT_AVATAR_ID = "shadow-soldier";
export const FALLBACK_AVATAR_SRC = ASSETS._fallback;

export const LOCAL_CATEGORIES = [
  { id: "soldiers-warriors", name: "Soldiers & Warriors" },
  { id: "skulls-dark", name: "Skulls & Dark" },
  { id: "cars-racing", name: "Cars & Racing" },
  { id: "robots-scifi", name: "Robots & Sci-Fi" },
  { id: "animals-fantasy", name: "Animals & Fantasy" },
  { id: "anime-mystery", name: "Anime & Mystery" },
];

