export const LOCAL_AVATARS = Object.entries(BY_CATEGORY).flatMap(([category, list]) =>
  list.map(([id, name]) => ({ id, name, category })),
);

const NAMES = new Map(LOCAL_AVATARS.map((a) => [a.id, a.name]));

if (import.meta.env.DEV) {
  const missing = LOCAL_AVATARS.filter((a) => !ASSETS[a.id]).map((a) => a.id);
  if (missing.length) console.warn(`[avatars] no asset for: ${missing.join(", ")}`);
}

export function hasAvatarAsset(id) {
  return typeof id === "string" && id !== "_fallback" && Object.hasOwn(ASSETS, id);
}

/** Image URL for an avatar id; never throws, never returns undefined. */
export function getAvatarSrc(id) {
  if (hasAvatarAsset(id)) return ASSETS[id];
  return ASSETS[DEFAULT_AVATAR_ID] || FALLBACK_AVATAR_SRC;
}

/** Catalog id to show for a user object (legacy users without one get the default). */
export function resolveAvatarId(id) {
  return hasAvatarAsset(id) ? id : DEFAULT_AVATAR_ID;
}

export function getAvatarName(id) {
  return NAMES.get(id) || NAMES.get(DEFAULT_AVATAR_ID) || "Avatar";
}

/**
 * Normalises a GET /api/avatars payload into { avatars, categories,
 * defaultAvatarId }, dropping entries without a local asset. Returns null
 * for an unusable payload so callers keep the local catalog.
 */
export function normalizeCatalog(data) {
  const avatars = Array.isArray(data?.avatars)
    ? data.avatars.filter((a) => a && hasAvatarAsset(a.id)).map((a) => ({
        id: a.id,
        name: a.name || getAvatarName(a.id),
        category: a.category,
      }))
    : [];
  if (!avatars.length) return null;
  const used = new Set(avatars.map((a) => a.category));
  const categories = (Array.isArray(data.categories) && data.categories.length ? data.categories : LOCAL_CATEGORIES)
    .filter((c) => c && used.has(c.id));
  return {
    avatars,
    categories,
    defaultAvatarId: hasAvatarAsset(data.defaultAvatarId) ? data.defaultAvatarId : DEFAULT_AVATAR_ID,
  };
}

export const LOCAL_CATALOG = {
  avatars: LOCAL_AVATARS,
  categories: LOCAL_CATEGORIES,
  defaultAvatarId: DEFAULT_AVATAR_ID,
};
